unit = input("Source unit (C/F): ").strip().lower()
text = input("Temperature: ")
result = None
if unit != "c" and unit != "f":
    status = "unknown unit"
else:
    try:
        value = float(text)
        if unit == "c":
            result = value * 9 / 5 + 32
        else:
            result = (value - 32) * 5 / 9
        status = "ok"
    except ValueError:
        status = "invalid number"
print(status)
if status == "ok":
    print(f"{result:.2f}")
